// RelayServiceHandler is an implementation of the harness.relay.v1.RelayService service.
type RelayServiceHandler interface {
	// --- Host side --------------------------------------------------------------------------------------
	// Registers the calling device process as a host. Returns a host id used by the other host RPCs.
	// One host per client process; `harness daemon` registers with daemon = true and its allowed roots.
	RegisterHost(context.Context, *connect.Request[v1.RegisterHostRequest]) (*connect.Response[v1.RegisterHostResponse], error)
	// Downstream channel for a host: commands for its registered sessions, spawn requests, tunnel requests and
	// heartbeats. One stream per host id: opening a new one closes the previous (ABORTED). On open, the server
	// first redelivers all unacked commands of the host's sessions (in command order), then live ones.
	OpenHostStream(context.Context, *connect.Request[v1.OpenHostStreamRequest], *connect.ServerStream[v1.OpenHostStreamResponse]) error
	// Registers (or takes over) a session on this host and returns its new epoch.
	RegisterSession(context.Context, *connect.Request[v1.RegisterSessionRequest]) (*connect.Response[v1.RegisterSessionResponse], error)
	// The session ended or is no longer remote-controllable from this host.
	UnregisterSession(context.Context, *connect.Request[v1.UnregisterSessionRequest]) (*connect.Response[v1.UnregisterSessionResponse], error)
	// Upstream batch of events for one session. Recommended batching: flush every 100 ms or 64 events.
	PublishEvents(context.Context, *connect.Request[v1.PublishEventsRequest]) (*connect.Response[v1.PublishEventsResponse], error)
	// Acknowledges commands (with their outcome). Unacked commands are redelivered.
	AckCommands(context.Context, *connect.Request[v1.AckCommandsRequest]) (*connect.Response[v1.AckCommandsResponse], error)
	// Host liveness, session status summary and local activity (for presence).
	Heartbeat(context.Context, *connect.Request[v1.HeartbeatRequest]) (*connect.Response[v1.HeartbeatResponse], error)
	// Registers a tunnel to a local port (preview) or a PTY on this host.
	RegisterTunnel(context.Context, *connect.Request[v1.RegisterTunnelRequest]) (*connect.Response[v1.RegisterTunnelResponse], error)
	CloseTunnel(context.Context, *connect.Request[v1.CloseTunnelRequest]) (*connect.Response[v1.CloseTunnelResponse], error)
	// --- Viewer side ------------------------------------------------------------------------------------
	// Hosts of the caller with their online state and remote-controllable sessions.
	ListHosts(context.Context, *connect.Request[v1.ListHostsRequest]) (*connect.Response[v1.ListHostsResponse], error)
	// History after after_seq, FlushComplete, then live events (see FlushGate above). Opening the stream marks
	// the viewer present (UNFOCUSED until UpdatePresence says otherwise).
	SubscribeSession(context.Context, *connect.Request[v1.SubscribeSessionRequest], *connect.ServerStream[v1.SubscribeSessionResponse]) error
	UpdatePresence(context.Context, *connect.Request[v1.UpdatePresenceRequest]) (*connect.Response[v1.UpdatePresenceResponse], error)
	// Commands. Each wraps the matching harness.agent.v1 request and returns once the command is queued
	// (or, with wait_for_ack, once the host acked it or the wait timed out). Effects are observed as events.
	SendUserMessage(context.Context, *connect.Request[v1.SendUserMessageRequest]) (*connect.Response[v1.SendUserMessageResponse], error)
	Interrupt(context.Context, *connect.Request[v1.InterruptRequest]) (*connect.Response[v1.InterruptResponse], error)
	// RespondToPermission and AnswerQuestion always wait for the host ack (wait_for_ack is implied, max ~10 s)
	// so the UI can show "already answered" (OUTCOME_ALREADY_RESOLVED) right away. If the host does not ack in
	// time, delivery = QUEUED and the outcome arrives as a PermissionResolved / QuestionResolved event.
	RespondToPermission(context.Context, *connect.Request[v1.RespondToPermissionRequest]) (*connect.Response[v1.RespondToPermissionResponse], error)
	AnswerQuestion(context.Context, *connect.Request[v1.AnswerQuestionRequest]) (*connect.Response[v1.AnswerQuestionResponse], error)
	SetModel(context.Context, *connect.Request[v1.SetModelRequest]) (*connect.Response[v1.SetModelResponse], error)
	SetEffort(context.Context, *connect.Request[v1.SetEffortRequest]) (*connect.Response[v1.SetEffortResponse], error)
	SetPermissionMode(context.Context, *connect.Request[v1.SetPermissionModeRequest]) (*connect.Response[v1.SetPermissionModeResponse], error)
	SetOutputStyle(context.Context, *connect.Request[v1.SetOutputStyleRequest]) (*connect.Response[v1.SetOutputStyleResponse], error)
	SetAutoContinue(context.Context, *connect.Request[v1.SetAutoContinueRequest]) (*connect.Response[v1.SetAutoContinueResponse], error)
	RemoveQueuedMessage(context.Context, *connect.Request[v1.RemoveQueuedMessageRequest]) (*connect.Response[v1.RemoveQueuedMessageResponse], error)
	// RespondToPlan waits for the host ack like RespondToPermission (first answer wins).
	RespondToPlan(context.Context, *connect.Request[v1.RespondToPlanRequest]) (*connect.Response[v1.RespondToPlanResponse], error)
	StopTask(context.Context, *connect.Request[v1.StopTaskRequest]) (*connect.Response[v1.StopTaskResponse], error)
	CloseSession(context.Context, *connect.Request[v1.CloseSessionRequest]) (*connect.Response[v1.CloseSessionResponse], error)
	// Long-running: return once queued (or acked with wait_for_ack); progress and the result arrive as
	// Compacted / Rewound events.
	Compact(context.Context, *connect.Request[v1.CompactRequest]) (*connect.Response[v1.CompactResponse], error)
	Rewind(context.Context, *connect.Request[v1.RewindRequest]) (*connect.Response[v1.RewindResponse], error)
	// Query commands: the server holds the call until the host acks with a result (max ~10 s), otherwise
	// UNAVAILABLE (host offline or slow).
	SuggestFiles(context.Context, *connect.Request[v1.SuggestFilesRequest]) (*connect.Response[v1.SuggestFilesResponse], error)
	ListCheckpoints(context.Context, *connect.Request[v1.ListCheckpointsRequest]) (*connect.Response[v1.ListCheckpointsResponse], error)
	ListTasks(context.Context, *connect.Request[v1.ListTasksRequest]) (*connect.Response[v1.ListTasksResponse], error)
	ListOutputStyles(context.Context, *connect.Request[v1.ListOutputStylesRequest]) (*connect.Response[v1.ListOutputStylesResponse], error)
	// "New session on machine X in folder Y". Only to daemon hosts, only under their allowed roots (checked by
	// the server and again by the host). Held until the host acks with the created session (max ~30 s).
	SpawnSession(context.Context, *connect.Request[v1.SpawnSessionRequest]) (*connect.Response[v1.SpawnSessionResponse], error)
	// Tunnels from the viewer's side.
	// Asks a host to open a tunnel (preview port or PTY); held until the host registered it (max ~10 s).
	RequestTunnel(context.Context, *connect.Request[v1.RequestTunnelRequest]) (*connect.Response[v1.RequestTunnelResponse], error)
	ListTunnels(context.Context, *connect.Request[v1.ListTunnelsRequest]) (*connect.Response[v1.ListTunnelsResponse], error)
	// Issues a short-lived, single-use access URL for the browser (sets an owner-only cookie on the preview
	// origin). Only the tunnel owner may call it.
	AuthorizeTunnel(context.Context, *connect.Request[v1.AuthorizeTunnelRequest]) (*connect.Response[v1.AuthorizeTunnelResponse], error)
	// "Keep computer awake" for the session, on the machine running it.
	SetKeepAwake(context.Context, *connect.Request[v1.SetKeepAwakeRequest]) (*connect.Response[v1.SetKeepAwakeResponse], error)
	// The session's subagents, on the machine running it. Query commands like ListTasks: the stop's result is the agent
	// as it ended up.
	StopSubagent(context.Context, *connect.Request[v1.StopSubagentRequest]) (*connect.Response[v1.StopSubagentResponse], error)
	GetSubagentTranscript(context.Context, *connect.Request[v1.GetSubagentTranscriptRequest]) (*connect.Response[v1.GetSubagentTranscriptResponse], error)
	// A note from another session of the user. Delivered as a reminder on the far side, never as a user message. It waits
	// for an offline host for up to 30 days (options.ttl_seconds does not shorten or extend that), and for the session's
	// new owner if it moves. FAILED_PRECONDITION when the session is closed: the caller leaves the note in the user's
	// SESSION_NOTES document instead.
	SendSessionNote(context.Context, *connect.Request[v1.SendSessionNoteRequest]) (*connect.Response[v1.SendSessionNoteResponse], error)
	// Starts or dismisses a proposal of a session (harness.agent.v1.ResolveSessionProposalRequest): held for the host's
	// ack, and the session's SessionProposal event follows.
	ResolveSessionProposal(context.Context, *connect.Request[v1.ResolveSessionProposalRequest]) (*connect.Response[v1.ResolveSessionProposalResponse], error)
}

